<?php require 'config/database.php';require 'config/functions.php';session_start();if($_SERVER['REQUEST_METHOD']!=='POST'||!hash_equals($_SESSION['csrf']??'',$_POST['csrf']??'')){flash('error','Invalid delete request.');header('Location: traps.php');exit;}$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);if($id){$q=$pdo->prepare("DELETE FROM grease_traps WHERE id=?");$q->execute([$id]);flash('success',$q->rowCount()?'Grease trap deleted successfully.':'Trap not found.');}else flash('error','Invalid trap.');header('Location: traps.php');exit;